bind.setValue:
(el, v) => {
  const etiquetas = {idea: 'Idea clave', ejemplo: 'Ejemplo', contraejemplo: 'Contraejemplo', atencion: 'Atención',
    definicion: 'Definición', practica: 'Antes de practicar', tarea: 'En la tarea', ampliacion: 'Ampliación'};
  Object.keys(etiquetas).forEach(c => el.classList.remove(c));
  el.classList.add(v);
  const etiqueta = el.querySelector('span.etiqueta');
  if (etiqueta) {
    etiqueta.textContent = etiquetas[v];
  }
}
